// Verify the HMAC session token issued by /webhook/auth/google.
// Format: v1.<payload-b64url>.<sig-b64url>, payload { uid, exp }.
const crypto = require('crypto');
const req = $input.first().json || {};
const headers = req.headers || {};
const token = String(headers['x-user-token'] || headers['X-User-Token'] || '').trim();
const secret = $env.AUTH_TOKEN_SECRET || '';
let uid = '';
if (token && secret) {
  try {
    const parts = token.split('.');
    if (parts.length === 3 && parts[0] === 'v1') {
      const payloadB64 = parts[1];
      const expected = crypto.createHmac('sha256', secret).update(payloadB64).digest('base64url');
      const a = Buffer.from(parts[2]);
      const b = Buffer.from(expected);
      if (a.length === b.length && crypto.timingSafeEqual(a, b)) {
        const payload = JSON.parse(Buffer.from(payloadB64, 'base64url').toString());
        if (payload.uid && payload.exp * 1000 > Date.now()) uid = String(payload.uid);
      }
    }
  } catch (e) {
    uid = '';
  }
}
return [{ json: { uid } }];
